#' Process a list of \code{seas} elements 
#' 
#' Process a list of \code{seas} objects generated by the \code{seasonal} package to 
#' find the elements that are greater than or less than a particular limit for a 
#' diagnostic.
#' Information on generating adjustments of multiple time series stored in a
#' list object with the \code{seasonal} package can be found in 
#' \insertCite{rprojectAdjustingMultiple;textual}{sautilities}. 
#' 
#' Version 4.0, 2026-03-04
#'
#' @param seas_obj_list List object of \code{seas} objects generated from a call 
#'        of \code{seas} on a list consisting of individual time series.
#'        This is a required entry.
#' @param this_key Character string containing keyword of the \code{udg} function 
#'        of the \code{seasonal} package that returns a numeric value. 
#'        For more information on the \code{udg} function, 
#'        see \insertCite{Sax2018;textual}{sautilities}.
#'        Default is \code{'autoout'}.
#' @param this_limit Numeric object which serves as the limit of the diagnostic 
#'        referred to in \code{this_key}.  
#'        Default is \code{'5'}
#' @param this_abs Logical scalar that indicates whether the absolute value is taken 
#'        of the numbers before the comparison is made. 
#'        Default is \code{FALSE}.
#' @param this_position Integer scalar; if the result is a vector, the position of 
#'        number that the comparison is made to.
#'        Default is \code{1}.
#' @param greater_than Logical scalar that specified whether the element names 
#'        returned are greater than (\code{TRUE}) or less than (\code{FALSE}) 
#'        the limit specified in \code{this_limit}.
#'        Default is \code{TRUE}.
#' @return A vector of list element names where this_key is greater than or 
#'         less than the limit specified in \code{this_limit}. 
#'         If nothing matches, the function will output the string \code{'none'}.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @examples 
#' emp_seas_list <- 
#'    seasonal::seas(employment_data_mts, 
#'       transform.function = "log", 
#'       arima.model = "(0 1 1)(0 1 1)", 
#'       forecast.maxlead=36,
#'       check.print = c( "pacf", "pacfplot" ), 
#'       x11 = "", 
#'       slidingspans = "")
#' emp_seas_update <- 
#'    Filter(function(x) inherits(x, "seas"), emp_seas_list)
#' xt_bad_m7 <- 
#'    udg_series(emp_seas_update, this_key = 'f3.m07', this_limit = 1.2)
#' xt_bad_q2 <- 
#'    udg_series(emp_seas_update, this_key = 'f3.qm2', this_limit = 1.2)
#' @export
udg_series <- 
   function(seas_obj_list = NULL, 
      this_key = "autoout", 
      this_limit = 5, 
      this_abs = FALSE, 
      this_position = 1, 
      greater_than = TRUE) {
    # Author: Brian C. Monsell (OEUS) Version 4.0, 2026-03-04
    
    # check if a value is specified for \code{this_seas_list}
    if (is.null(seas_obj_list)) {
        stop("must specify a list of seas objects")
    } else {
        if (!is.list(seas_obj_list)) {
            stop("must specify a list")
        }
    }
    
    # filter elements of the list that are not \code{seas} objects
    seas_obj_list_update <-
      Filter(function(x) inherits(x, "seas"), seas_obj_list)

    # extract diagnostic \code{this_key} from \code{seas_obj_list_update}
    udg_list <- 
		lapply(seas_obj_list_update, function(x) try(seasonal::udg(x, this_key)))
    
    # check \code{udg_error} for try errors if try errors found, print out error messages and 
    # set \code{udg_error} to NULL
    udg_error <- which_error(udg_list)
    if (length(udg_error > 1)) {
        udg_list[[udg_error]] <- NULL
        print(paste("try errors found - ", udg_error))
    }
    
    # if there are no entries in \code{udg_error}, print error message and return NULL
    if (length(udg_list) == 0) {
        print("No series to process.")
        return(NULL)
    }
	
	# if \code{udg_list} contains vectors or matrices, will extract the vectors 
	# from the list and extract the desired element.
	
    length_vector <- 
		sum(unlist(lapply(udg_list, length)) > 1)
	if (length_vector > 0) {
		n_list <- length(udg_list)
		udg_name <- names(udg_list)
		for (i in 1:n_list) {
			this_name <- udg_name[i]
			udg_list[[this_name]] <- udg_list[[this_name]][this_position]
		}
	}
    
    # if \code{this_abs} is true, return the element names on the list that are either 
    # greater than or less thanin absolute value than \code{this_limit}
    if (this_abs) {
        if (greater_than) {
            udg_names <- names(udg_list)[as.vector(abs(unlist(udg_list)) > this_limit)]
        } else {
            udg_names <- names(udg_list)[as.vector(abs(unlist(udg_list)) < this_limit)]
        }
    } else {
        # else, return the element names on the list that are either greater than or 
        #       less than \code{this_limit}
        if (greater_than) {
            udg_names <- names(udg_list)[as.vector(unlist(udg_list) > this_limit)]
        } else {
            udg_names <- names(udg_list)[as.vector(unlist(udg_list) < this_limit)]
        }
    }
    
    # return either the names or \code{'none'} if there are no names
    if (length(udg_names) > 0) {
        return(udg_names)
    } else {
        return("none")
    }
}
